mapper.select:
SELECT 
FROM TBL_TRANSACTION_TYPE


        AND TRANSACTION_TYPE_CODE LIKE CONCAT('%', #{transactionTypeCode}, '%')


        AND TRANSACTION_TYPE_NAME LIKE CONCAT('%', #{transactionTypeName}, '%')


        AND TRANSACTION_CATEGORY = #{transactionCategory}


        AND TRANSACTION_DIRECTION = #{transactionDirection}


        AND RISK_LEVEL = #{riskLevel}


        AND IS_ENABLED = #{isEnabled}


        AND ORG_ID = #{orgId}


ORDER BY SORT_ORDER ASC, CREATE_TIME DESC

SELECT COUNT(1)
FROM TBL_TRANSACTION_TYPE
WHERE TRANSACTION_TYPE_CODE = #{transactionTypeCode}

    AND TRANSACTION_TYPE_ID != #{excludeId}
